#[tokio::test]
async fn an_identical_command_request_replays_its_original_record() {
    let Some(pool) = crate::test_support::test_pool() else {
        eprintln!("skipping: ACKPLANE_TEST_DATABASE_URL is not set");
        return;
    };
    let suffix = unique_id("work-command-replay");
    let tenant_id = format!("tenant-{suffix}");
    let repository_id = format!("repository-{suffix}");
    let command = request(&tenant_id, &repository_id, &suffix);
    let now = SystemTime::now();
    let store = WorkCommandStore::connect(&pool)
        .await
        .expect("the command store should connect");

    let first = store
        .record_request(&command, now)
        .await
        .expect("the first request should persist");
    let replay = store
        .record_request(&command, now)
        .await
        .expect("the identical request should replay");

    assert!(!first.idempotent_replay);
    assert!(replay.idempotent_replay);
    assert_eq!(replay.command, first.command);
}

#[tokio::test]
async fn a_changed_request_under_one_idempotency_key_is_refused_without_overwrite() {
    let Some(pool) = crate::test_support::test_pool() else {
        eprintln!("skipping: ACKPLANE_TEST_DATABASE_URL is not set");
        return;
    };
    let suffix = unique_id("work-command-conflict");
    let tenant_id = format!("tenant-{suffix}");
    let repository_id = format!("repository-{suffix}");
    let original = request(&tenant_id, &repository_id, &suffix);
    let mut changed = original.clone();
    changed.rationale = "Attempt to overwrite the original request.".to_owned();
    let now = SystemTime::now();
    let store = WorkCommandStore::connect(&pool)
        .await
        .expect("the command store should connect");

    let created = store
        .record_request(&original, now)
        .await
        .expect("the original request should persist");
    let conflict = store.record_request(&changed, now).await;
    let replay = store
        .record_request(&original, now)
        .await
        .expect("the original request should still replay");

    assert!(matches!(
        conflict,
        Err(WorkCommandStoreError::IdempotencyConflict)
    ));
    assert!(replay.idempotent_replay);
    assert_eq!(replay.command, created.command);
}

