#[tokio::test]
async fn a_verified_in_scope_principal_records_a_replayable_pending_confirmation() {
    let Some(pool) = crate::test_support::test_pool() else {
        eprintln!("skipping: ACKPLANE_TEST_DATABASE_URL is not set");
        return;
    };
    let suffix = unique_id("work-command-authorized");
    let tenant_id = format!("tenant-{suffix}");
    let repository_id = format!("repository-{suffix}");
    let command = request(&tenant_id, &repository_id, &suffix);
    let now = SystemTime::now();
    let service = WorkCommandService::connect(&pool)
        .await
        .expect("the command service should connect");

    let first = service
        .submit(
            verified_authorization(&tenant_id, &repository_id, &suffix),
            command.clone(),
            now,
        )
        .await
        .expect("an authorized command should record a preview");
    let replay = service
        .submit(
            verified_authorization(&tenant_id, &repository_id, &suffix),
            command,
            now,
        )
        .await
        .expect("an identical authorized command should replay");

    let WorkCommandServiceOutcome::PendingConfirmation {
        command: first_command,
        receipt: first_receipt,
        idempotent_replay: first_replay,
    } = first
    else {
        panic!("an authorized command must enter pending confirmation");
    };
    let WorkCommandServiceOutcome::PendingConfirmation {
        command: replay_command,
        receipt: replay_receipt,
        idempotent_replay: replayed,
    } = replay
    else {
        panic!("an identical command must replay its pending confirmation");
    };

    assert!(!first_replay);
    assert!(replayed);
    assert_eq!(first_command, replay_command);
    assert_eq!(first_receipt, replay_receipt);
    assert_eq!(
        first_receipt.outcome,
        WorkCommandOutcome::PendingConfirmation
    );
    assert_eq!(
        first_receipt.evidence_refs,
        vec![format!("policy-{suffix}")]
    );
}

/// Seeds one `delegated_claims` row via a raw connection (no store exposes
/// claim creation to this crate yet) and returns the `lease_expires_at`
/// Postgres actually stored -- `TIMESTAMPTZ` truncates to microseconds, so a
/// test asserting `ReleaseLease` matches must compare against this
/// round-tripped value, never the untruncated in-memory `SystemTime` it was
/// seeded from.
async fn seed_claim(
    database_url: &str,
    tenant_id: &str,
    repository_id: &str,
    task_id: &str,
    owner_id: &str,
    now: SystemTime,
) -> SystemTime {
    let client = raw_client(database_url).await;
    let row = client
        .query_one(
            "INSERT INTO delegated_claims (tenant_id, repository_id, task_id, owner_id, branch, \
                 claim_started_at, lease_expires_at, claim_lapses, paths, symbols) \
             VALUES ($1,$2,$3,$4,'main',$5,$5,0,ARRAY[]::text[],ARRAY[]::text[]) \
             RETURNING lease_expires_at",
            &[&tenant_id, &repository_id, &task_id, &owner_id, &now],
        )
        .await
        .expect("seeding a claim should succeed");
    row.get("lease_expires_at")
}

async fn set_task_claimed(
    database_url: &str,
    tenant_id: &str,
    repository_id: &str,
    task_id: &str,
    owner_id: &str,
    now: SystemTime,
) {
    const CLAIMED: i16 = 2;
    let client = raw_client(database_url).await;
    client
        .execute(
            "UPDATE work_tasks SET state = $4, owner_id = $5, lease_expires_at = $6 \
             WHERE tenant_id = $1 AND repository_id = $2 AND task_id = $3",
            &[
                &tenant_id,
                &repository_id,
                &task_id,
                &CLAIMED,
                &owner_id,
                &now,
            ],
        )
        .await
        .expect("marking the task claimed should succeed");
}

async fn seed_wait(
    database_url: &str,
    tenant_id: &str,
    repository_id: &str,
    task_id: &str,
    wait_id: &str,
    suffix: &str,
    already_answered: bool,
) {
    let client = raw_client(database_url).await;
    if already_answered {
        client
            .execute(
                "INSERT INTO work_task_waits (tenant_id, repository_id, wait_id, task_id, \
                     question, asked_by, answered_by, answer, answered_at) \
                 VALUES ($1,$2,$3,$4,$5,$6,$6,'already answered',now())",
                &[
                    &tenant_id,
                    &repository_id,
                    &wait_id,
                    &task_id,
                    &format!("Question {suffix}"),
                    &format!("asker-{suffix}"),
                ],
            )
            .await
            .expect("seeding an already-answered wait should succeed");
    } else {
        client
            .execute(
                "INSERT INTO work_task_waits (tenant_id, repository_id, wait_id, task_id, \
                     question, asked_by) VALUES ($1,$2,$3,$4,$5,$6)",
                &[
                    &tenant_id,
                    &repository_id,
                    &wait_id,
                    &task_id,
                    &format!("Question {suffix}"),
                    &format!("asker-{suffix}"),
                ],
            )
            .await
            .expect("seeding a wait should succeed");
    }
}

